#pragma once

#include <mutex>
#include <utility>

// java.util.concurrent.atomic.AtomicReference 模板桩。
// 编译器（llvm-mingw clang++）不支持 std::atomic<std::shared_ptr>，
// 因此用 mutex + 普通值存储实现原子语义；T 为原生指针或智能指针时同样适用。
template<typename T>
class AtomicReference {
public:
    AtomicReference() = default;
    explicit AtomicReference(T initial) : value_(std::move(initial)) {}

    // 原子读取当前值
    T get() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return value_;
    }

    // 原子写入新值
    void set(T newValue) {
        std::lock_guard<std::mutex> lock(mutex_);
        value_ = std::move(newValue);
    }

    // CAS：当前值 == expected 时替换为 update，返回是否成功
    bool compareAndSet(T expected, T update) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (value_ == expected) {
            value_ = std::move(update);
            return true;
        }
        return false;
    }

private:
    mutable std::mutex mutex_;
    T value_{};
};
